import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  const upperGradient = smoothstep(0.08, 0.9, backdropY);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.012, 0.012, 0.016),
      upperGradient
    ),
    smoothstep(0.12, 0.78, backdropY)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.55, 2.12);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.52
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.08, -0.18);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGeometry = new PlaneGeometry(3.2, 1.82);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, 0);
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const innerGeometry = new PlaneGeometry(3.08, 1.7);
  const innerMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.18
  });
  const inner = new Mesh(innerGeometry, innerMaterial);
  inner.position.set(0, 0, 0.012);
  root.add(inner);
  resources.push(innerGeometry, innerMaterial);

  const railGeometry = new PlaneGeometry(0.055, 1.5);
  const railMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const rail = new Mesh(railGeometry, railMaterial);
  rail.position.set(-1.43, 0, 0.025);
  root.add(rail);
  resources.push(railGeometry, railMaterial);

  const topRuleGeometry = new PlaneGeometry(2.35, 0.018);
  const topRuleMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.52
  });
  const topRule = new Mesh(topRuleGeometry, topRuleMaterial);
  topRule.position.set(0.18, 0.63, 0.025);
  root.add(topRule);
  resources.push(topRuleGeometry, topRuleMaterial);

  const markerGeometry = new PlaneGeometry(0.12, 0.12);
  const markerMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const marker = new Mesh(markerGeometry, markerMaterial);
  marker.position.set(1.24, -0.62, 0.026);
  marker.rotation.z = Math.PI * 0.25;
  root.add(marker);
  resources.push(markerGeometry, markerMaterial);

  const imageUrl = config?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      texture.anisotropy = 4;
      cardMaterial.map = texture;
      cardMaterial.color.set(colors.paper);
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }
    timelines.length = 0;

    const disposedResources = new Set();
    for (const resource of resources) {
      if (!resource || disposedResources.has(resource)) continue;
      disposedResources.add(resource);
      resource.dispose?.();
    }

    root.traverse((object) => {
      object.geometry?.dispose?.();
      if (Array.isArray(object.material)) {
        object.material.forEach((material) => material?.dispose?.());
      } else {
        object.material?.dispose?.();
      }
    });
  };

  return root;
}
